import json
import sys
from pathlib import Path

# Turns an IR file into C++ that runs the schedule with NCCL.
# Usage: python3 compiler/codegen.py ir/n4.json gen/gen_n4.cu
#
# The output defines gen_stragglar_allreduce (see gen/gen_stragglar.h).
# Each round becomes one ncclGroupStart/ncclGroupEnd block:
#   "write": dst receives straight into its buffer.
#   "add":   dst receives into its scratch buffer, then adds it to its buffer
#            with reduce_add after the block ends.

HEADER = """\
// Generated by compiler/codegen.py from {source}. Do not edit by hand.

#include "gen_stragglar.h"

#include <cassert>

static __global__ void reduce_add(float* dst, float* src, int count) {{
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i < count) {{
    dst[i] += src[i];
  }}
}}

void gen_stragglar_allreduce(float** d_buffers, float** d_tempbufs, int* devs,
                             cudaStream_t* streams, ncclComm_t* comms,
                             int numRanks, size_t chunkSize) {{
  assert(numRanks == {n});
  int numBlocks = (chunkSize + 128 - 1) / 128;
"""


def chunk_ptr(rank, chunk):
    return f"d_buffers[{rank}] + {chunk} * chunkSize"


def gen_round(i, ops):
    lines = ["", f"  // round {i}", "  ncclGroupStart();"]
    for op in ops:
        src, dst, chunk = op["src"], op["dst"], op["chunk"]
        if op["op"] == "add":
            recv_into = f"d_tempbufs[{dst}]"
        elif op["op"] == "write":
            recv_into = chunk_ptr(dst, chunk)
        else:
            sys.exit(f"round {i}: unknown op type {op['op']!r}")
        lines.append(f"  ncclSend({chunk_ptr(src, chunk)}, chunkSize, ncclFloat, {dst}, comms[{src}], streams[{src}]);")
        lines.append(f"  ncclRecv({recv_into}, chunkSize, ncclFloat, {src}, comms[{dst}], streams[{dst}]);")
    lines.append("  ncclGroupEnd();")

    for op in ops:
        if op["op"] == "add":
            dst, chunk = op["dst"], op["chunk"]
            lines.append(f"  cudaSetDevice(devs[{dst}]);")
            lines.append(f"  reduce_add<<<numBlocks, 128, 0, streams[{dst}]>>>({chunk_ptr(dst, chunk)}, d_tempbufs[{dst}], chunkSize);")
    return lines


if len(sys.argv) != 3:
    sys.exit("Usage: python3 compiler/codegen.py <ir_file> <output_file>")

ir_file, output_file = sys.argv[1], sys.argv[2]
ir = json.loads(Path(ir_file).read_text())

code = [HEADER.format(source=ir_file, n=ir["n"]).rstrip("\n")]
for i, ops in enumerate(ir["rounds"]):
    code.extend(gen_round(i, ops))
code.append("}")

Path(output_file).write_text("\n".join(code) + "\n")
print(f"Wrote {output_file}: n={ir['n']}, {len(ir['rounds'])} rounds")
